For testing metadata you should manually remove all keys and only allow certain ones something like this


```js
const reservedKeys = [
  // mandatory keys
  'PhotometricInterpretation',
  'StudyInstanceUID',
  'SeriesInstanceUID',
  'SOPInstanceUID',
  'Rows',
  'Columns',
  'PixelRepresentation', // For most cases, might work without it with our defaults
  'imageId',
  'wadoRoot',
  'Modality', // it is not really really needed but most likely we need this
  'SOPClassUID', // very good chance we need this

  // For MPR
  'ImagePositionPatient',
  'ImageOrientationPatient',
  'PixelSpacing',
  'BitsAllocated',

  // For rendering
  'RescaleIntercept', // for visual purposes but you can modify with window level later
  'RescaleSlope', // for visual purposes
  'WindowCenter',
  'WindowWidth',

  // // For SEG
  // 'ReferencedSeriesSequence',
  // 'SharedFunctionalGroupsSequence',
  // 'PerFrameFunctionalGroupsSequence',
  // 'FrameOfReferenceUID',

  // For RTSTRUCT
  // 'FrameOfReferenceUID',
  // 'ROIContourSequence',
  // 'StructureSetROISequence',
  // 'ReferencedFrameOfReferenceSequence',

  // For some datasets
  // 'InstanceNumber', // for sorting

  // For US
  'NumberOfFrames',
  'SequenceOfUltrasoundRegions', // for measurements
  'FrameTime', // if you want to use the frame time specified in the header to run the cine

  // For SR
  // 'ConceptNameCodeSequence',
  // 'ContentSequence',
  // 'ContentTemplateSequence',
  // 'CurrentRequestedProcedureEvidenceSequence',
  // 'ContentTemplateSequence',
  // 'CodingSchemeIdentificationSequence',

  // For PT SUV corrected
  // 'RadiopharmaceuticalInformationSequence',
  // 'SeriesDate',
  // 'SeriesTime',
  // 'CorrectedImage',
  // 'Units',
  // 'RadiopharmaceuticalInformationSequence',
  // 'DecayCorrection',
  // 'AcquisitionDate',
  // 'AcquisitionTime',
  // 'PatientWeight',

  // For PDF
  // 'EncapsulatedDocument',

  // For Video
  // 'NumberOfFrames',
  // 'PixelData',
];

function filterByReservedKeys(obj) {
  return Object.fromEntries(Object.entries(obj).filter(([key]) => reservedKeys.includes(key)));
}

window.filterByReservedKeys = filterByReservedKeys;
```

